/*
 * MEDCHECK service worker.
 *
 * Hand-written rather than generated by vite-plugin-pwa: the plugin would be a new
 * build-time dependency for roughly this much logic, and the caching policy here
 * needs to be auditable line by line, because in a clinical tool the wrong policy
 * is actively dangerous.
 *
 * Two rules drive every decision below:
 *
 *  1. NEVER cache /api/. Those responses carry the user's medicine basket, their
 *     interaction analysis, and a bearer session. Serving a stale interaction
 *     result would be worse than serving none -- a user could be shown an
 *     all-clear for a basket they have since changed. Same-origin /api requests are
 *     passed straight through, untouched and unrecorded.
 *
 *  2. Never let a cached app shell strand users on an old build. Navigations are
 *     network-first, so a fresh deploy is picked up on the next online load; the
 *     cached shell is only used when the network genuinely fails.
 *
 * Only the shell (HTML, icons, manifest) and Vite's content-hashed /assets/ files
 * are cached. Hashed filenames change whenever their content changes, so
 * cache-first is safe for them by construction.
 *
 * Bump CACHE_VERSION to evict everything on the next activation.
 */

const CACHE_VERSION = 'v1';
const SHELL_CACHE = `medcheck-shell-${CACHE_VERSION}`;
const ASSET_CACHE = `medcheck-assets-${CACHE_VERSION}`;
const OWNED_CACHES = new Set([SHELL_CACHE, ASSET_CACHE]);

// Kept deliberately short. /assets/* filenames are hash-stamped at build time and
// therefore unknowable here; they populate ASSET_CACHE lazily on first request.
const SHELL_URLS = [
  '/',
  '/index.html',
  '/favicon.svg',
  '/icon-maskable.svg',
  '/manifest.webmanifest',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Individually, not addAll: addAll rejects atomically, so one 404 (an icon
      // renamed, say) would abort the whole install and leave the app with no
      // offline capability at all.
      await Promise.all(
        SHELL_URLS.map((url) =>
          cache.add(new Request(url, { cache: 'reload' })).catch(() => {})
        )
      );
      // Activate immediately instead of waiting for every tab to close, so a
      // security or correctness fix in this file takes effect on the next load.
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith('medcheck-') && !OWNED_CACHES.has(name))
          .map((name) => caches.delete(name))
      );
      await self.clients.claim();
    })()
  );
});

/** Vite emits every bundled JS/CSS chunk under /assets/ with a content hash. */
function isHashedAsset(url) {
  return url.pathname.startsWith('/assets/');
}

function isShellAsset(url) {
  return SHELL_URLS.includes(url.pathname);
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Only GET is cacheable, and only same-origin traffic is ours to reason about.
  // Cross-origin requests (Google Fonts, api.fda.gov) fall through to the network
  // with no interception.
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Rule 1: the API is off limits. Also skip the SW itself, so a broken worker can
  // always be replaced by a plain reload.
  if (url.pathname.startsWith('/api/') || url.pathname === '/sw.js') return;

  // Navigations: network-first with an offline fallback to the cached shell. React
  // Router owns the path once index.html is running, so any navigation can be
  // satisfied by the shell.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(request);
          const cache = await caches.open(SHELL_CACHE);
          cache.put('/index.html', fresh.clone());
          return fresh;
        } catch {
          const cache = await caches.open(SHELL_CACHE);
          return (
            (await cache.match('/index.html')) ||
            (await cache.match('/')) ||
            new Response('Offline and no cached copy of MEDCHECK is available.', {
              status: 503,
              headers: { 'Content-Type': 'text/plain' },
            })
          );
        }
      })()
    );
    return;
  }

  if (isHashedAsset(url) || isShellAsset(url)) {
    event.respondWith(
      (async () => {
        const cacheName = isHashedAsset(url) ? ASSET_CACHE : SHELL_CACHE;
        const cache = await caches.open(cacheName);
        const hit = await cache.match(request);
        if (hit) return hit;

        const response = await fetch(request);
        // Only 200s are stored. Caching an opaque or error response would pin a
        // failure in place until the next version bump.
        if (response.ok && response.type === 'basic') {
          cache.put(request, response.clone());
        }
        return response;
      })()
    );
  }
});
